import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

// A fixed source list prevents accidentally shipping local credentials or
// generated material. Regenerated by test/prepack, never maintained by hand.
const source = new URL("../../../skills/evestack/", import.meta.url);
const paths = [
  "SKILL.md",
  "references/build-an-agent.md",
  "references/cli.md",
  "references/dashboard.md",
  "references/troubleshooting.md",
];
const version = JSON.parse(
  readFileSync(new URL("../package.json", import.meta.url), "utf8"),
).version;
const release = JSON.parse(
  readFileSync(
    new URL("../../../release-manifest.json", import.meta.url),
    "utf8",
  ),
);
if (release.packages.evestack !== version)
  throw new Error("Regenerate the release manifest before packing the CLI.");
const files = paths.map((path) => {
  const content = readFileSync(new URL(path, source), "utf8");
  if (Buffer.byteLength(content) > 256 * 1024)
    throw new Error(`Skill pack file exceeds 256 KiB: ${path}`);
  return {
    path,
    content,
    sha256: createHash("sha256").update(content).digest("hex"),
  };
});
const pack =
  JSON.stringify(
    {
      formatVersion: 1,
      name: "evestack",
      version,
      source: "bundled",
      runtime: release.runtime,
      files,
    },
    null,
    2,
  ) + "\n";
if (Buffer.byteLength(pack) > 1024 * 1024)
  throw new Error("Skill pack exceeds 1 MiB.");
writeFileSync(new URL("../agent-pack.json", import.meta.url), pack);
console.log(`Bundled ${files.length} setup files for evestack ${version}.`);
